//! 📨️ The native command wire measures and writes the original typed command into its exact retained input pages.
use semio_framework_job::{StepContext,OriginalSourceBinding,OriginalTurnFailure,OriginalConstructionDemand,admit_original_construction,close_original_retained_step};
use semio_framework_value::{RetirementDemand,RetainedCloneProgress,RetainedCloneStep,ValueError,ValueRefusalKind,retirement::RetireOwned,retained_clone::RetainedCloneClose};
use semio_framework::action_bus::{RetainedToolWireInput,ToolWirePage,TOOL_WIRE_PAGE_BYTES};
pub use semio_framework_os_store_operation_wire::ArtifactPreparedOperationSource;
use semio_framework_os_store_operation_wire::{ArtifactPreparedOperationCursor,ArtifactPreparedOperationProgress};
use std::mem::{ManuallyDrop,size_of};
/// 🫳️ A declared codec borrows only the original immutable command and its static authored schema.
pub type OriginalCommandWireSource<C>=for<'a>fn(&'a C)->ArtifactPreparedOperationSource<'a>;
/// 🧳️ No command header, body or page escapes before both native codec passes close.
pub struct ArtifactOriginalCommandWire<C:RetireOwned+Send+Sync+'static>{binding:OriginalSourceBinding,decoder:(u64,u64),body:usize,command:ManuallyDrop<Option<Box<C>>>,source:OriginalCommandWireSource<C>,cursor:ArtifactPreparedOperationCursor,wire:ManuallyDrop<Option<RetainedToolWireInput>>,scratch:[u8;64],page:[u8;TOOL_WIRE_PAGE_BYTES],length:usize,offset:usize,page_len:usize,measured:usize,written:usize,maximum:usize,phase:u8,closing:bool,retirement:RetainedCloneClose}
fn invalid()->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,"native command wire lost its original source, extent or receiving continuation")}
fn header<T>()->RetirementDemand{RetirementDemand{copy_bytes:size_of::<T>(),depth:1,..Default::default()}}
fn original(d:RetirementDemand)->OriginalConstructionDemand{OriginalConstructionDemand{items:1,copy_bytes:d.copy_bytes,capacity_bytes:d.capacity_bytes,release_bytes:d.release_bytes,depth:d.depth}}
fn progress(d:RetirementDemand)->RetainedCloneProgress{RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,retained_capacity_bytes:d.capacity_bytes,released_bytes:d.release_bytes}}
fn codec_progress(p:ArtifactPreparedOperationProgress)->RetainedCloneProgress{RetainedCloneProgress{copied_items:p.processed_items,copied_bytes:p.copied_bytes,retained_capacity_bytes:p.retained_capacity_bytes,released_bytes:p.released_bytes}}
const META:usize=size_of::<(usize,usize,u8,bool)>();
impl<C:RetireOwned+Send+Sync+'static> ArtifactOriginalCommandWire<C>{
 pub fn birth_demands()->RetirementDemand{RetirementDemand{copy_bytes:size_of::<Self>()+size_of::<Option<Box<C>>>(),capacity_bytes:size_of::<Self>(),depth:1,..Default::default()}}
 /// 🌱️ One fresh frame receives the exact original command box without copying its business payload.
 pub fn admit(command:&mut Option<Box<C>>,source:OriginalCommandWireSource<C>,maximum:usize,cx:&mut StepContext<'_>,output:&mut Option<Box<Self>>)->Result<bool,OriginalTurnFailure>{if command.is_none(){return Err(invalid().into())}let binding=OriginalSourceBinding::borrow(cx);let body=cx.retained_grant().maximum_copy_bytes;let d=Self::birth_demands();admit_original_construction(cx,output,original(d),|control|{let decoder=(control.ledger_identity(),control.retirement_recipient_identity().ok_or_else(invalid)?);Ok((Box::write(Box::<Self>::new_uninit(),Self{binding,decoder,body,command:ManuallyDrop::new(command.take()),source,cursor:Default::default(),wire:ManuallyDrop::new(None),scratch:[0;64],page:[0;TOOL_WIRE_PAGE_BYTES],length:0,offset:0,page_len:0,measured:0,written:0,maximum,phase:0,closing:false,retirement:Default::default()}),progress(d)))})}
 fn validate(&self,cx:&StepContext<'_>)->Result<(),OriginalTurnFailure>{if !self.binding.matches(cx)||cx.native_receiving_identity()!=Some(self.decoder){return Err(invalid().into())}Ok(())}
 pub fn original_command(&self)->Option<&C>{self.command.as_ref().map(|command|command.as_ref())}
 pub fn ready(&self)->bool{!self.closing&&self.phase==7}
 pub fn demands(&self)->Result<RetirementDemand,ValueError>{if self.closing{return self.close_demands()}let mut d=match self.phase{
  0|4 if !self.cursor.complete&&self.offset==self.length=>RetirementDemand{copy_bytes:self.cursor.next_minimum_copy_bytes().max(64),capacity_bytes:self.cursor.next_capacity_byte_demand()?,depth:128,..Default::default()},
  0|4 if self.offset<self.length=>RetirementDemand{copy_bytes:self.length-self.offset,depth:1,..Default::default()},
  0=>header::<u8>(),1|6=>self.cursor.retirement_demands()?,2=>RetainedToolWireInput::original_birth_demands(self.measured,self.maximum)?,3=>header::<ArtifactPreparedOperationCursor>(),4 if self.cursor.complete&&self.offset==self.length&&self.page_len==0=>header::<u8>(),4|5=>RetirementDemand{copy_bytes:3*size_of::<ToolWirePage>()+self.page_len,depth:1,..Default::default()},7=>return self.take_demands(),_=>return Err(invalid()),};d.copy_bytes=d.copy_bytes.checked_add(META).ok_or_else(invalid)?;d.depth=d.depth.max(1);Ok(d)}
 /// ✍️ Each original turn selects one codec action, at most sixty-four appended bytes or one actual fixed wire page.
 pub fn advance(&mut self,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.validate(cx)?;if self.closing{return Err(invalid().into())}if self.ready(){return Ok(true)}if cx.is_cancelled(){return Err(ValueError::literal(ValueRefusalKind::Canceled,"native command wire cancelled").into())}let d=self.demands()?;let mut done=None;admit_original_construction(cx,&mut done,original(d),|_|{let g=semio_framework_value::RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes-META,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth};let p=match self.phase{
  0|4 if self.offset<self.length=>{let count=(self.length-self.offset).min(TOOL_WIRE_PAGE_BYTES-self.page_len);if self.phase==0{self.measured=self.measured.checked_add(count).filter(|length|*length<=self.maximum).ok_or_else(||ValueError::literal(ValueRefusalKind::OwnershipLimit,"native command wire exceeds its declared maximum"))?;}else{self.page[self.page_len..self.page_len+count].copy_from_slice(&self.scratch[self.offset..self.offset+count]);self.page_len+=count;self.written+=count;}self.offset+=count;if self.phase==4&&self.page_len==TOOL_WIRE_PAGE_BYTES{self.phase=5}RetainedCloneProgress{copied_items:1,copied_bytes:count,..Default::default()}},
  0|4 if !self.cursor.complete=>{let command=self.command.as_ref().ok_or_else(invalid)?;let step=self.cursor.advance((self.source)(command),&mut self.scratch,g).map_err(|error|error.reason)?;self.length=step.written_bytes;self.offset=0;codec_progress(step)},
  0=>{self.phase=1;progress(header::<u8>())},
  1|6=>{let p=self.cursor.close(g).map_err(|error|error.reason)?;if p.complete{self.phase=if self.phase==1{2}else{7}}codec_progress(p)},
  2=>{let(wire,p)=RetainedToolWireInput::admit_original(self.measured,self.maximum,g)?.ok_or_else(invalid)?;*self.wire=Some(wire);self.phase=3;p},
  3=>{self.cursor=Default::default();self.phase=4;progress(header::<ArtifactPreparedOperationCursor>())},
  4 if self.page_len==0=>{if self.written!=self.measured{return Err(invalid())}self.wire.as_mut().ok_or_else(invalid)?.seal().map_err(|_|invalid())?;self.phase=6;progress(header::<u8>())},
  4|5=>{let page=ToolWirePage::try_copy_from(&self.page[..self.page_len]).map_err(|_|invalid())?;self.wire.as_mut().ok_or_else(invalid)?.admit_page(page).map_err(|_|invalid())?;let p=progress(RetirementDemand{copy_bytes:3*size_of::<ToolWirePage>()+self.page_len,..Default::default()});self.page_len=0;self.phase=4;p},
  _=>return Err(invalid()),};let mut p=p;p.copied_items=p.copied_items.max(1);p.copied_bytes=p.copied_bytes.checked_add(META).ok_or_else(invalid)?;Ok(((),p))})?;Ok(self.ready())}
 pub fn take_demands(&self)->Result<RetirementDemand,ValueError>{if !self.ready(){return Err(invalid())}Ok(header::<(Option<Box<C>>,Option<Box<C>>,RetainedToolWireInput,RetainedToolWireInput,u8)>())}
 /// 🤝️ Exact source and wire owners transfer together after both canonical traversals close.
 pub fn take_into(&mut self,command:&mut Option<Box<C>>,wire:&mut Option<RetainedToolWireInput>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.validate(cx)?;if command.is_some()||wire.is_some(){return Err(invalid().into())}let d=self.take_demands()?;let mut done=None;admit_original_construction(cx,&mut done,original(d),|_|{*command=self.command.take();*wire=self.wire.take();self.phase=8;Ok(((),progress(d)))})}
 pub fn close_demands(&self)->Result<RetirementDemand,ValueError>{if !self.closing{return Ok(header::<bool>())}if !self.cursor.closed{return self.cursor.retirement_demands()}if let Some(wire)=self.wire.as_ref(){if wire.terminal_is_empty(){return Ok(header::<Option<RetainedToolWireInput>>())}return Ok(RetirementDemand{copy_bytes:wire.next_close_copy_byte_demand()?,release_bytes:wire.next_close_release_byte_demand()?,depth:wire.next_close_depth_demand()?,..Default::default()})}if !self.retirement.is_empty(){return self.retirement.demands(self.body)}if self.command.is_some(){return self.retirement.next_owner_demands::<Box<C>>(true,&None,self.body)}Ok(Default::default())}
 /// ♻️ Cancellation preserves the exact original decoder, source and initialized wire prefix through physical closure.
 pub fn close_step(&mut self,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.validate(cx)?;if self.terminal_is_empty(){return Ok(true)}let d=self.close_demands()?;close_original_retained_step(cx,d,|g|{if !self.closing{self.closing=true;return Ok(RetainedCloneStep::Progress(progress(d)))}if !self.cursor.closed{let p=self.cursor.close(g).map_err(|error|error.reason)?;return Ok(RetainedCloneStep::Progress(codec_progress(p)))}if let Some(wire)=self.wire.as_mut(){if wire.terminal_is_empty(){self.wire.take();return Ok(RetainedCloneStep::Progress(progress(d)))}return Ok(RetainedCloneStep::Progress(wire.close_step(g)?.progress()))}if !self.retirement.is_empty(){return self.retirement.select(self.body)?.step(g)}if self.command.is_some(){return Ok(self.retirement.begin_granted(&mut self.command,g)?.unwrap_or(RetainedCloneStep::Progress(Default::default())))}Ok(RetainedCloneStep::Complete(Default::default()))})?;Ok(self.terminal_is_empty())}
 pub fn terminal_is_empty(&self)->bool{self.command.is_none()&&self.wire.is_none()&&self.cursor.closed&&self.retirement.is_empty()}
 pub fn release_demands()->RetirementDemand{RetirementDemand{release_bytes:size_of::<Self>(),depth:1,..Default::default()}}
}
impl<C:RetireOwned+Send+Sync+'static> Drop for ArtifactOriginalCommandWire<C>{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"native command wire reached Drop before its original owners closed")}}
